def f(I):
    from collections import Counter
    cnt=Counter(x for r in I for x in r); bg=cnt.most_common(1)[0][0]
    H,W=len(I),len(I[0])
    comps=components(I,bg)
    bars=sorted([c for c in comps if len(set(p[0] for p in c))==1 and len(c)>=2],key=min)
    shape=max(comps,key=len) if len(comps)>2 else comps[-1]
    shapes=[c for c in comps if c not in bars]
    cells=[p for c in shapes for p in c]
    C=Counter(I[p[0]][p[1]] for p in cells).most_common(1)[0][0]
    out=[[I[r][c] for c in range(W)] for r in range(H)]
    def paint(rs,cs,color):
        for r,c in [(r,c) for r in rs for c in cs]:
            pass
        for r,c in zip(rs,cs):
            pass
        # fill from max_r down, painting only over bg cells
        for r in range(max(rs)+1,H):
            for c in range(min(cs),max(cs)+1):
                if I[r][c]==bg: out[r][c]=color
    for s in shapes:
        rs=[p[0] for p in s]; cs=[p[1] for p in s]
        sr0,sr1=min(rs),max(rs); scl,sce=min(cs),max(cs)
        for b in bars:
            Lr=b[0][0]; br=max(p[1] for p in b)
            shift=br-sce
            cl,ce=scl+shift,sce+shift
            # copy extends down from bar row
            for r in range(Lr+1,H):
                for c in range(cl,ce+1):
                    if I[r][c]==bg: out[r][c]=C
        # original shape cells extend down
        for r,c in s:
            for rr in range(r+1,H):
                if I[rr][c]==bg: out[rr][c]=C
    for p in cells: out[p[0]][p[1]]=4
    return out

